<?php $base=$type==='page'?'pages':'posts'; ?>
<div class="toolbar"><form class="filterbar" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search title or slug…"><select name="status"><option value="">All statuses</option><option value="published"<?= selected($status,'published') ?>>Published</option><option value="draft"<?= selected($status,'draft') ?>>Draft</option></select><button class="btn" type="submit">Filter</button></form><a class="btn primary" href="/admin/<?= e($base) ?>/create">+ New <?= e($type) ?></a></div>
<section class="panel"><div class="panel-head"><div><h2><?= (int)$pagination['total'] ?> <?= e($type) ?><?= (int)$pagination['total']===1?'':'s' ?></h2><p>Manage publication, SEO metadata and content.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Title</th><th>Status</th><th>Author</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?= e($item['title']) ?></strong><small class="table-sub">/<?= $type==='post'?'blog/':'' ?><?= e($item['slug']) ?></small></td><td><span class="badge <?= $item['status']==='published'?'success':'warning' ?>"><?= e($item['status']) ?></span></td><td><?= e($item['author_name']) ?></td><td class="muted"><?= e($item['updated_at']) ?></td><td class="right"><div class="actions"><a class="btn small" href="/admin/<?= e($base) ?>/<?= (int)$item['id'] ?>/edit">Edit</a><form method="post" action="/admin/<?= e($base) ?>/<?= (int)$item['id'] ?>/delete" data-confirm="Delete this item permanently?"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" class="empty-cell">No matching content.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($pagination['pages']>1):?><nav class="pagination"><?php for($i=1;$i<=$pagination['pages'];$i++):?><a class="<?= $i===$pagination['page']?'active':'' ?>" href="?page=<?= $i ?>&q=<?= urlencode($q) ?>&status=<?= urlencode($status) ?>"><?= $i ?></a><?php endfor;?></nav><?php endif;?>